import java.io.*; import java.util.*; public class TestClass { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter wr = new PrintWriter(System.out); String line1 = br.readLine(); if (line1 == null) return; int N = Integer.parseInt(line1.trim()); String[] arr_C = br.readLine().split(" "); int[] C = new int[N]; for(int i_C = 0; i_C < N; i_C++) { C[i_C] = Integer.parseInt(arr_C[i_C]); } List<Integer> resultList = new ArrayList<Integer>(); Stack<Integer> stack = new Stack<Integer>(); for(int i = 0; i < N; i++) { if(C[i] > 0) { stack.push(C[i]); } else if(!stack.isEmpty()) { resultList.add(stack.pop()); } } for(int i = 0; i < resultList.size(); i++) { wr.print(resultList.get(i)); if(i < resultList.size() - 1) { wr.print(" "); } } wr.println(); wr.close(); br.close(); } }